update public.home_photos p set sort_order=a.i-1 from unnest(array[2,3,5,7,19,20,8,13,14,16,1,4,6,11,12,15,18,0,17,9,10]) with ordinality a(orig,i) where p.home_id='sycamore' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[1,4,6,8,9,13,14,17,15,3,19,20,2,7,12,18,0,10,5,16,11]) with ordinality a(orig,i) where p.home_id='oasis' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[2,4,7,9,14,1,3,18,21,19,13,5,6,10,0,20,15,16,22,8,11,23,12,17]) with ordinality a(orig,i) where p.home_id='boujee-xl' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[11,12,14,0,1,7,10,21,20,3,15,16,8,9,13,17,4,2,5,6,18,19,22]) with ordinality a(orig,i) where p.home_id='lil-easy' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
