update public.home_photos p set sort_order=a.i-1 from unnest(array[0,2,1,3,5,4,6]) with ordinality a(orig,i) where p.home_id='tulip' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[2,0,1,3,4]) with ordinality a(orig,i) where p.home_id='buttercup' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[11,2,10,15,16,1,4,5,7,13,6,9,12,17,3,14,0,8]) with ordinality a(orig,i) where p.home_id='redwood' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[6,13,16,2,5,1,3,10,0,8,14,15,4,7,9,11,12]) with ordinality a(orig,i) where p.home_id='birch' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[0,1,4,7,5,13,6,11,12,14,2,8,9,10,3]) with ordinality a(orig,i) where p.home_id='aspen' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[4,15,1,10,14,12,7,11,3,6,13,2,5,9,0,8]) with ordinality a(orig,i) where p.home_id='truman' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[4,7,5,6,9,10,8,11,2,3,0,1]) with ordinality a(orig,i) where p.home_id='oak' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[10,13,4,5,9,8,6,7,2,1,3,11,0,12]) with ordinality a(orig,i) where p.home_id='maple' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[1,4,3,6,5,8,2,7,0]) with ordinality a(orig,i) where p.home_id='dogwood' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.home_photos p set sort_order=a.i-1 from unnest(array[2,8,9,3,4,6,7,12,1,5,10,11,0]) with ordinality a(orig,i) where p.home_id='boone' and p.url like '%-'||to_char(a.orig,'FM00')||'.jpg';
update public.homes h set cover_image=(select p.url from public.home_photos p where p.home_id=h.id order by p.sort_order limit 1) where h.id in ('sycamore','oasis','boujee-xl','lil-easy','jackson','tulip','buttercup','redwood','birch','aspen','truman','oak','maverick','maple','dogwood','boone');